export const historyWandsCups: Record<string, { en: Story; 'zh-CN': Story }> = Object.fromEntries(
  Object.entries(entries).map(([id, pair]) => {
    const [suit, number] = id.split('-');
    return [id, { en: story(pair.en, suit as 'wands' | 'cups', Number(number), false), 'zh-CN': story(pair['zh-CN'], suit as 'wands' | 'cups', Number(number), true) }];
  }),
);
